contracts/NFTCollection1155.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.4;
import "@openzeppelin/contracts/token/ERC1155/ERC1155.sol";

contract NFTCollection1155 is ERC1155 {
    uint256 public currentTokenId = 0;

    struct CollectionInfo {
        uint256 totalSupply;
        uint256 minted;
        string uri;
    }

    mapping(uint256 => CollectionInfo) public collections;

    constructor() ERC1155("") {}

    function createCollectionForMarketplace(
        string memory _uri,
        uint256 _supply,
        address marketplace
    ) external returns (uint256) {
        currentTokenId++;
        collections[currentTokenId] = CollectionInfo({
            totalSupply: _supply,
            minted: _supply,
            uri: _uri
        });
        _mint(marketplace, currentTokenId, _supply, "");
        return currentTokenId;
    }

    function createCollection(string memory _uri, uint256 _supply) external returns (uint256) {
        currentTokenId++;
        collections[currentTokenId] = CollectionInfo({
            totalSupply: _supply,
            minted: _supply,
            uri: _uri
        });
        _mint(msg.sender, currentTokenId, _supply, "");
        return currentTokenId;
    }

    function uri(uint256 id) public view override returns (string memory) {
        return collections[id].uri;
    }
}

contracts/NFTMarketplace.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.4;

import "@openzeppelin/contracts/utils/Counters.sol";
import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC1155/IERC1155.sol";
import "@openzeppelin/contracts/token/ERC1155/utils/ERC1155Receiver.sol";

import "hardhat/console.sol";

interface INFTCollection1155 {
    function createCollectionForMarketplace(
        string memory uri,
        uint256 totalSupply,
        address marketplace
    ) external returns (uint256);

    function createCollection(
        string memory uri,
        uint256 totalSupply
    ) external returns (uint256);
}

contract NFTMarketplace is ERC721URIStorage, ERC1155Receiver {
    using Counters for Counters.Counter;

    Counters.Counter private _tokenIds;
    Counters.Counter private _itemsSold;
    Counters.Counter private _itemIds1155;

    uint256 listingPrice = 25; // 25 WEB

    address private owner;
    IERC20 public webToken;
    address public immutable nftCollection1155;

    mapping(uint256 => MarketItem) private idMarketItem;

    struct MarketItem {
        uint256 tokenId;
        address payable seller;
        address payable owner;
        uint256 price;
        bool sold;
    }

    event idMarketItemCreated(
        uint256 indexed tokenId,
        address seller,
        address owner,
        uint256 price,
        bool sold
    );

    struct MarketItem1155 {
        uint256 itemId;
        address nftContract;
        uint256 tokenId;
        uint256 amount;
        uint256 amountAvailable;
        uint256 totalPrice;
        uint256 price;
        address payable seller;
        address payable owner;
        bool sold;
    }

    struct OwnedNFT {
        uint256 tokenId;
        uint256 balance;
        address nftContract;
    }

    mapping(uint256 => MarketItem1155) private idMarketItem1155;

    mapping(address => uint256[]) private userListings1155;
    mapping(uint256 => bool) private activeListings;

    event MarketItem1155Created(
        uint256 indexed itemId,
        uint256 tokenId,
        uint256 amount,
        uint256 amountAvailable,
        uint256 totalPrice,
        uint256 price,
        address seller,
        address owner
    );

    event MarketItem1155Sold(
        uint256 indexed itemId,
        uint256 tokenId,
        uint256 amountBought,
        uint256 price,
        address seller,
        address buyer
    );

    event MarketItem1155Relisted(
        uint256 indexed itemId,
        uint256 tokenId,
        uint256 amount,
        uint256 newPrice,
        address seller
    );

    constructor(
        address _webTokenAddress,
        address _nftCollection1155Address
    ) ERC721("NFT Metavarse Token", "NFTMT") {
        owner = payable(msg.sender);
        webToken = IERC20(_webTokenAddress);
        nftCollection1155 = _nftCollection1155Address;
    }

    function updateListingPrice(uint256 _listingPrice) public {
        require(msg.sender == owner, "Only owner can update listing price");
        listingPrice = _listingPrice;
    }

    function getListingPrice() public view returns (uint256) {
        return listingPrice;
    }

    function createToken(
        string memory _tokenURI,
        uint256 _price
    ) public returns (uint256) {
        _tokenIds.increment();

        uint256 newTokenId = _tokenIds.current();

        _mint(msg.sender, newTokenId);
        _setTokenURI(newTokenId, _tokenURI);

        createMarketItem(newTokenId, _price);

        return newTokenId;
    }

    function createMarketItem(uint256 _tokenId, uint256 _price) private {
        require(_price > 0, "Price must be al lest 1");

        bool success = webToken.transferFrom(
            msg.sender,
            address(this),
            listingPrice
        );
        require(success, "Token transfer failed for listing price");

        idMarketItem[_tokenId] = MarketItem(
            _tokenId,
            payable(msg.sender),
            payable(address(this)),
            _price,
            false
        );

        _transfer(msg.sender, address(this), _tokenId);

        emit idMarketItemCreated(
            _tokenId,
            msg.sender,
            address(this),
            _price,
            false
        );
    }

    function createToken1155(
        string memory _uri,
        uint256 _totalSupply,
        uint256 _pricePerToken
    ) external returns (uint256 itemId) {
        require(_totalSupply > 0, "Supply > 0");
        require(_pricePerToken > 0, "Price > 0");

        bool success = webToken.transferFrom(
            msg.sender,
            address(this),
            listingPrice
        );
        require(success, "Listing fee failed");

        uint256 tokenId = INFTCollection1155(nftCollection1155)
            .createCollectionForMarketplace(_uri, _totalSupply, address(this));

        _itemIds1155.increment();
        itemId = _itemIds1155.current();

        uint256 _price = _pricePerToken * _totalSupply;

        idMarketItem1155[itemId] = MarketItem1155({
            itemId: itemId,
            nftContract: nftCollection1155,
            tokenId: tokenId,
            amount: _totalSupply,
            amountAvailable: _totalSupply,
            totalPrice: _price,
            price: _pricePerToken,
            seller: payable(msg.sender),
            owner: payable(address(this)),
            sold: false
        });

        activeListings[itemId] = true;
        userListings1155[msg.sender].push(itemId);

        emit MarketItem1155Created(
            itemId,
            tokenId,
            _totalSupply,
            _totalSupply,
            _price,
            _pricePerToken,
            msg.sender,
            address(this)
        );

        return itemId;
    }

    function reSellToken(uint256 _tokenId, uint256 _price) public {
        require(
            idMarketItem[_tokenId].owner == msg.sender,
            "Only item owner con perform this operation"
        );

        bool success = webToken.transferFrom(
            msg.sender,
            address(this),
            listingPrice
        );
        require(success, "Token transfer failed for listing fee");

        idMarketItem[_tokenId].sold = false;
        idMarketItem[_tokenId].price = _price;
        idMarketItem[_tokenId].seller = payable(msg.sender);
        idMarketItem[_tokenId].owner = payable(address(this));

        _itemsSold.decrement();

        _transfer(msg.sender, address(this), _tokenId);
    }

    function createMarketSale(uint256 _tokenId) public {
        uint256 price = idMarketItem[_tokenId].price / 1 ether;

        bool success = webToken.transferFrom(msg.sender, address(this), price);
        require(success, "Token transfer failed for NFT price");

        webToken.transfer(owner, listingPrice);

        uint256 sellerProceeds = price;

        webToken.transfer(idMarketItem[_tokenId].seller, sellerProceeds);

        idMarketItem[_tokenId].owner = payable(msg.sender);
        idMarketItem[_tokenId].sold = true;
        idMarketItem[_tokenId].seller = payable(address(0));

        _itemsSold.increment();

        _transfer(address(this), msg.sender, _tokenId);
    }

    function buyToken1155(uint256 _itemId, uint256 _buyQuantity) public {
        require(_buyQuantity > 0, "Quantity must be > 0");

        MarketItem1155 storage item = idMarketItem1155[_itemId];
        require(item.amountAvailable >= _buyQuantity, "Not enough available");
        require(!item.sold, "Item fully sold");

        uint256 totalPrice = (item.price / 1 ether) * _buyQuantity;

        bool success = webToken.transferFrom(
            msg.sender,
            address(this),
            totalPrice
        );
        require(success, "Payment failed");

        uint256 sellerProceeds = totalPrice;

        if (item.owner == address(this)) {
            webToken.transfer(owner, listingPrice);
            sellerProceeds -= listingPrice;
        }
        webToken.transfer(item.seller, sellerProceeds);

        IERC1155(item.nftContract).safeTransferFrom(
            address(this),
            msg.sender,
            item.tokenId,
            _buyQuantity,
            ""
        );

        item.amountAvailable -= _buyQuantity;
        item.totalPrice -= totalPrice;

        if (item.amountAvailable == 0) {
            item.sold = true;
            activeListings[_itemId] = false;
        }

        emit MarketItem1155Sold(
            _itemId,
            item.tokenId,
            _buyQuantity,
            item.price,
            item.seller,
            msg.sender
        );
    }

    function reSellToken1155(
        uint256 _tokenId,
        uint256 _sellAmount,
        uint256 _newPrice
    ) public {
        require(_sellAmount > 0, "Amount > 0");
        require(_newPrice > 0, "Price > 0");

        uint256 userBalance = IERC1155(nftCollection1155).balanceOf(
            msg.sender,
            _tokenId
        );
        require(userBalance >= _sellAmount, "Insufficient balance");

        bool success = webToken.transferFrom(
            msg.sender,
            address(this),
            listingPrice
        );
        require(success, "Listing fee failed");

        IERC1155(nftCollection1155).safeTransferFrom(
            msg.sender,
            address(this),
            _tokenId,
            _sellAmount,
            ""
        );

        _itemIds1155.increment();
        uint256 newItemId = _itemIds1155.current();

        uint256 _totalPrice = _newPrice * _sellAmount;

        idMarketItem1155[newItemId] = MarketItem1155({
            itemId: newItemId,
            nftContract: nftCollection1155,
            tokenId: _tokenId,
            amount: _sellAmount,
            amountAvailable: _sellAmount,
            totalPrice: _totalPrice,
            price: _newPrice,
            seller: payable(msg.sender),
            owner: payable(address(this)),
            sold: false
        });

        userListings1155[msg.sender].push(newItemId);
        activeListings[newItemId] = true;

        emit MarketItem1155Created(
            newItemId,
            _tokenId,
            _sellAmount,
            _sellAmount,
            _totalPrice,
            _newPrice,
            msg.sender,
            address(this)
        );
    }

    function fetchMarketItems() public view returns (MarketItem[] memory) {
        uint256 itemCount = _tokenIds.current();
        uint256 unSoldItemCount = _tokenIds.current() - _itemsSold.current();
        uint256 currentIndex = 0;

        MarketItem[] memory items = new MarketItem[](unSoldItemCount);

        for (uint256 i = 0; i < itemCount; i++) {
            if (idMarketItem[i + 1].owner == address(this)) {
                uint256 currentId = i + 1;

                MarketItem storage currentItem = idMarketItem[currentId];

                items[currentIndex] = currentItem;

                currentIndex += 1;
            }
        }
        return items;
    }

    function fetchMyNFTs() public view returns (MarketItem[] memory) {
        uint256 totalCount = _tokenIds.current();
        uint256 itemCount = 0;
        uint256 currentIndex = 0;

        for (uint256 i = 0; i < totalCount; i++) {
            if (idMarketItem[i + 1].owner == msg.sender) {
                itemCount += 1;
            }
        }

        MarketItem[] memory items = new MarketItem[](itemCount);

        for (uint256 i = 0; i < totalCount; i++) {
            if (idMarketItem[i + 1].owner == msg.sender) {
                uint256 currentId = i + 1;

                MarketItem storage currentItem = idMarketItem[currentId];

                items[currentIndex] = currentItem;

                currentIndex += 1;
            }
        }
        return items;
    }

    function fetchItemsListed() public view returns (MarketItem[] memory) {
        uint256 totalCount = _tokenIds.current();
        uint256 itemCount = 0;
        uint256 currentIndex = 0;

        for (uint256 i = 0; i < totalCount; i++) {
            if (idMarketItem[i + 1].seller == msg.sender) {
                itemCount += 1;
            }
        }

        MarketItem[] memory items = new MarketItem[](itemCount);

        for (uint256 i = 0; i < totalCount; i++) {
            if (idMarketItem[i + 1].seller == msg.sender) {
                uint256 currentId = i + 1;

                MarketItem storage currentItem = idMarketItem[currentId];

                items[currentIndex] = currentItem;

                currentIndex += 1;
            }
        }
        return items;
    }

    function fetchMarketItems1155()
        public
        view
        returns (MarketItem1155[] memory)
    {
        uint256 itemCount = _itemIds1155.current();
        uint256 availableCount = 0;

        for (uint256 i = 1; i <= itemCount; i++) {
            if (
                idMarketItem1155[i].amountAvailable > 0 &&
                !idMarketItem1155[i].sold
            ) {
                availableCount++;
            }
        }

        MarketItem1155[] memory items = new MarketItem1155[](availableCount);
        uint256 currentIndex = 0;

        for (uint256 i = 1; i <= itemCount; i++) {
            if (
                idMarketItem1155[i].amountAvailable > 0 &&
                !idMarketItem1155[i].sold
            ) {
                items[currentIndex] = idMarketItem1155[i];
                currentIndex++;
            }
        }

        return items;
    }

    function onERC1155Received(
        address operator,
        address from,
        uint256 id,
        uint256 value,
        bytes calldata data
    ) external pure override returns (bytes4) {
        return this.onERC1155Received.selector;
    }

    function onERC1155BatchReceived(
        address operator,
        address from,
        uint256[] calldata ids,
        uint256[] calldata values,
        bytes calldata data
    ) external pure override returns (bytes4) {
        return this.onERC1155BatchReceived.selector;
    }

    function supportsInterface(
        bytes4 interfaceId
    )
        public
        view
        virtual
        override(ERC721URIStorage, ERC1155Receiver)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }
}

contracts/NFTStaking.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.4;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import "@openzeppelin/contracts/token/ERC1155/ERC1155.sol";
import "@openzeppelin/contracts/token/ERC1155/IERC1155.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol";

contract NFTStaking is IERC721Receiver {
  IERC20 public webToken;
  address public nft721Contract;
  address public nft1155Contract;
  address private owner;

  // uint256 public constant DAY_IN_SECONDS = 86400;
  // uint256[3] public durations = [30 * DAY_IN_SECONDS, 60 * DAY_IN_SECONDS, 90 * DAY_IN_SECONDS];

  uint256 public constant DAY_IN_SECONDS = 60;
  uint256[3] public durations = [30 * DAY_IN_SECONDS, 60 * DAY_IN_SECONDS, 90 * DAY_IN_SECONDS];

  struct StakeInfo {
    address staker;
    uint256 startTime;
    uint256 endTime;
    uint256 amount;
    uint256 tokenId;
    bool isERC721;
    bool active;
  }

  mapping(address => StakeInfo[]) public userStakes;
  uint256 public totalStakedValue;
  uint256 public rewardPool;

  event Staked(address staker, uint256 tokenId, uint256 amount, uint256 duration);
  event Unstaked(address staker, uint256 tokenId, uint256 amount, uint256 reward);

  constructor(address _webToken, address _nft721Contract, address _nft1155Contract) {
    owner = payable(msg.sender);
    webToken = IERC20(_webToken);
    nft721Contract = _nft721Contract;
    nft1155Contract = _nft1155Contract;
  }

  function depositReward(uint256 _amount) external {
    require(msg.sender == owner, "Ownable: caller is not the owner");
    webToken.transferFrom(msg.sender, address(this), _amount);
    rewardPool += _amount;
  }

  function stakeERC721(uint256 _tokenId, uint8 _durationIndex) external {
    require(_durationIndex < 3, "Invalid duration");
    require(IERC721(nft721Contract).ownerOf(_tokenId) == msg.sender, "Not owner of NFT");

    IERC721(nft721Contract).safeTransferFrom(msg.sender, address(this), _tokenId);

    uint256 endTime = block.timestamp + durations[_durationIndex];

    userStakes[msg.sender].push(StakeInfo({
      staker: msg.sender,
      startTime: block.timestamp,
      endTime: endTime,
      amount: 1,
      tokenId: _tokenId,
      isERC721: true,
      active: true
    }));

    emit Staked(msg.sender, _tokenId, 1, durations[_durationIndex]);
  }

  function stakeERC1155(uint256 _tokenId, uint256 _amount, uint8 _durationIndex) external {
    require(_durationIndex < 3, "Invalid duration");
    require(IERC1155(nft1155Contract).balanceOf(msg.sender, _tokenId) >= _amount, "Insufficient balance");

    IERC1155(nft1155Contract).safeTransferFrom(msg.sender, address(this), _tokenId, _amount, "");

    uint256 endTime = block.timestamp + durations[_durationIndex];

    userStakes[msg.sender].push(StakeInfo({
      staker: msg.sender,
      startTime: block.timestamp,
      endTime: endTime,
      amount: _amount,
      tokenId: _tokenId,
      isERC721: false,
      active: true
    }));

    emit Staked(msg.sender, _tokenId, _amount, durations[_durationIndex]);
  }

  function unstake(uint256 _stakeIndex) external {
    require(_stakeIndex < userStakes[msg.sender].length, "Invalid stake index");

    StakeInfo storage stake = userStakes[msg.sender][_stakeIndex];

    require(stake.active, "Not active");

    uint256 currentTime = block.timestamp;
    bool isEarly = currentTime < stake.endTime;

    uint256 timeStaked = currentTime - stake.startTime;
    uint256 dayStaked = timeStaked / DAY_IN_SECONDS;

    uint256 reward = 0;

    if (stake.isERC721) {
      uint256 baseRewardPerDay = 10; // 10 WEB per day
      reward = baseRewardPerDay * dayStaked; 
    } else {
      uint256 rewardPerTokenPerDay = 1; // 1 WEB per day
      reward = rewardPerTokenPerDay * stake.amount * dayStaked; 
    }

    if (isEarly) {
      reward = reward / 2;
    }

    require(rewardPool >= reward, "Insufficient reward pool");

    if (stake.isERC721) {
      IERC721(nft721Contract).safeTransferFrom(address(this), msg.sender, stake.tokenId);
    } else {
      IERC1155(nft1155Contract).safeTransferFrom(address(this), msg.sender, stake.tokenId, stake.amount, "");
    }

    webToken.transfer(msg.sender, reward);
    rewardPool -= reward;
    stake.active = false;

    emit Unstaked(msg.sender, stake.tokenId, stake.amount, reward);
  }

  function getUserStakes(address _user) external view returns (StakeInfo[] memory) {
    return userStakes[_user];
  }

  function getUserStakesCount(address _user) external view returns (uint256) {
    return userStakes[_user].length;
  }

  function onERC721Received(
        address operator,
        address from,
        uint256 tokenId,
        bytes calldata data
    ) external pure override returns (bytes4) {
        return IERC721Receiver.onERC721Received.selector;
    }
}

